use crossterm::{
    event::{self, Event, KeyCode, KeyEvent, KeyModifiers},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use ratatui::{
    backend::{Backend, CrosstermBackend},
    layout::{Constraint, Layout, Direction},
    style::{Color, Modifier, Style},
    text::{Line, Span},
    widgets::{Block, Borders, Paragraph, List, ListItem},
    Frame, Terminal,
};
use std::io::{self, stdout};
use std::path::{Path, PathBuf};
use std::fs;
use std::time::SystemTime;
use time::OffsetDateTime;

mod app;
mod ui;
mod events;

use app::App;

fn main() -> io::Result<()> {
    let args: Vec<String> = std::env::args().collect();

    // Parse arguments
    if args.len() > 1 {
        match args[1].as_str() {
            "-h" | "--help" => {
                print_help();
                return Ok(());
            }
            "-l" | "--log" => {
                run_with_log()
            }
            "--init" => {
                print_init();
                return Ok(());
            }
            path => {
                run_app(path.to_string())
            }
        }
    } else {
        let cwd = std::env::current_dir()?.to_string_lossy().to_string();
        run_app(cwd)
    }
}

fn run_app(start_path: String) -> io::Result<()> {
    enable_raw_mode()?;
    let mut stdout = stdout();
    execute!(stdout, EnterAlternateScreen)?;

    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let mut app = App::new(start_path)?;

    loop {
        terminal.draw(|f| ui::draw(f, &mut app))?;

        if event::poll(std::time::Duration::from_millis(250))? {
            if let Event::Key(key) = event::read()? {
                if !app.handle_key_event(key) {
                    break;
                }
            }
        }
    }

    disable_raw_mode()?;
    execute!(
        terminal.backend_mut(),
        LeaveAlternateScreen
    )?;
    terminal.show_cursor()?;

    // Print working directory if needed
    if let Some(last_dir) = &app.last_working_dir {
        println!("{}", last_dir);
    }

    Ok(())
}

fn run_with_log() -> io::Result<()> {
    // TODO: Implement logging
    let cwd = std::env::current_dir()?.to_string_lossy().to_string();
    run_app(cwd)
}

fn print_help() {
    println!("# felix v2.16.1");
    println!("A simple TUI file manager with vim-like keymapping.");
    println!();
    println!("## Usage");
    println!("`fx` => Show items in the current directory.");
    println!("`fx <directory path>` => Show items in the path.");
    println!("Both relative and absolute path available.");
    println!();
    println!("## Options");
    println!("`--help` | `-h`   => Print help.");
    println!("`--log`  | `-l`   => Launch the app, automatically generating a log file.");
    println!("`--init`          => Returns a shell script that can be sourcedfor");
    println!("                     for shell integration.");
    println!();
    println!("## Manual");
    println!("j / <Down>         :Go down.");
    println!("k / <Up>           :Go up.");
    println!("<C-d>              :Go down 1/2 page.");
    println!("<C-u>>             :Go up 1/2 page.");
    println!("h / <Left>         :Go to the parent directory if exists.");
    println!("l / <Right> / <CR> :Open item or change directory.");
    println!("gg                 :Go to the top.");
    println!("G                  :Go to the bottom.");
    println!("z<CR>              :Go to the home directory.");
    println!("z {{keyword}}<CR>    :Jump to a directory that matches the keyword.");
    println!("                    (zoxide required)");
    println!("<C-o>              :Jump backward.");
    println!("<C-i>              :Jump forward.");
    println!("i{{file name}}<CR>   :Create a new empty file.");
    println!("I{{dir name}}<CR>    :Create a new empty directory.");
    println!("o                  :Open item in a new window.");
    println!("e                  :Unpack archive/compressed file.");
    println!("dd                 :Delete and yank item.");
    println!("yy                 :Yank item.");
    println!("p                  :Put yanked item(s) from register zero");
    println!("                    in the current directory.");
    println!(":reg               :Show registers. To hide it, press v.");
    println!("\"ayy               :Yank item to register a.");
    println!("\"add               :Delete and yank item to register a.");
    println!("\"Ayy               :Append item to register a.");
    println!("\"Add               :Delete and append item to register a.");
    println!("\"ap                :Put item(s) from register a.");
    println!("V                  :Switch to the linewise visual mode.");
    println!("  - y              :In the visual mode, yank selected item(s).");
    println!("  - d              :In the visual mode, delete and yank selected item(s).");
    println!("  - \"ay            :In the visual mode, yank items to register a.");
    println!("  - \"ad            :In the visual mode, delete and yank items to register a.");
    println!("  - \"Ay            :In the visual mode, append items to register a.");
    println!("  - \"Ad            :In the visual mode, delete and append items to register a.");
    println!("  - c              :Rename selected items in default editor.");
    println!("u                  :Undo put/delete/rename.");
    println!("<C-r>              :Redo put/delete/rename.");
    println!("v                  :Toggle whether to show the preview.");
    println!("s                  :Toggle between vertical / horizontal split in the preview mode.");
    println!("<Alt-j>");
    println!(" / <Alt-<Down>>    :Scroll down the preview text.");
    println!("<Alt-k>");
    println!(" / <Alt-<Up>>      :Scroll up the preview text.");
    println!("<BS>               :Toggle whether to show hidden items.");
    println!("t                  :Toggle the sort order (name <-> modified time).");
    println!("c                  :Switch to the rename mode.");
    println!("/{{keyword}}         :Search items by a keyword.");
    println!("n                  :Go forward to the item that matches the keyword.");
    println!("N                  :Go backward to the item that matches the keyword.");
    println!(":                  :Switch to the command line.");
    println!("  - <C-r>a         :In the command line, paste item name in register a.");
    println!(":cd<CR>            :Go to the home directory.");
    println!(":cd {{path}}<CR>     :Go to the path.");
    println!(":e<CR>             :Reload the current directory.");
    println!(":config<CR>        :Go to the directory that contains the config file if exists.");
    println!(":trash<CR>         :Go to the trash directory.");
    println!(":empty<CR>         :Empty the trash directory.");
    println!(":h<CR>             :Show help.");
    println!(":q<CR>             :Exit.");
    println!("::{{command}}         :Execute a command e.g. :zip test *.md");
    println!("<Esc>              :Return to the normal mode.");
    println!("<C-h>              :Works as Backspace after `i`, `I`, `c`, `/`, `:` and `z`.");
    println!("ZZ                 :Exit without cd to last working directory");
    println!("                    (if `match_vim_exit_behavior` is `false`).");
    println!("ZQ                 :cd into the last working directory and exit");
    println!("                    (if shell setting is ready and `match_vim_exit_behavior is `false`).");
    println!();
    println!("## Preview feature");
    println!("By default, text files and directories can be previewed.");
    println!("To preview images, you need to install chafa (>= v1.10.0).");
    println!("Please see https://hpjansson.org/chafa/");
    println!();
    println!("## Configuration");
    println!();
    println!("*Both `config.yaml` and `config.yml` work.*");
    println!();
    println!("### Linux");
    println!("config file    : $XDG_CONFIG_HOME/felix/config.yaml(config.yml)");
    println!("trash directory: $XDG_DATA_HOME/felix/trash");
    println!("log files      : $XDG_DATA_HOME/felix/log");
    println!();
    println!("### macOS");
    println!("On macOS, felix looks for the config file in the following locations:");
    println!();
    println!("1. `$HOME/Library/Application Support/felix/config.yaml(config.yml)`");
    println!("2. `$HOME/.config/felix/config.yaml`");
    println!();
    println!("trash directory: $HOME/Library/Application Support/felix/trash");
    println!("log files      : $HOME/Library/Application Support/felix/log");
    println!();
    println!("### Windows");
    println!("config file     : $PROFILE\\AppData\\Roaming\\felix\\config.yaml(config.yml)");
    println!("trash directory : $PROFILE\\AppData\\Local\\felix\\trash");
    println!("log files       : $PROFILE\\AppData\\Local\\felix\\log");
    println!();
    println!("For more details, visit https://github.com/kyoheiu/felix");
}

fn print_init() {
    println!("# To be eval'ed in the calling shell");
    println!("  eval \"$(");
    println!("    if [ -n \"$XDG_RUNTIME_DIR\" ]; then");
    println!("      runtime_dir=\"$XDG_RUNTIME_DIR/felix\"");
    println!("    elif [ -n \"$TMPDIR\" ]; then");
    println!("      runtime_dir=\"$TMPDIR/felix\"");
    println!("    else");
    println!("      runtime_dir=/tmp/felix");
    println!("    fi");
    println!();
    println!("    mkdir -p \"$runtime_dir\"");
    println!();
    println!("    # Clean up leftover LWD files");
    println!("    find \"$runtime_dir\" -type f -and -mmin +1 -delete");
    println!();
    println!("    cat << EOF");
    println!("fx() {{");
    println!("  local RUNTIME_DIR=\"$runtime_dir\"");
    println!("  SHELL_PID=\\$\\$ command fx \"\\$@\"");
    println!();
    println!("  if [ -f \"\\$RUNTIME_DIR/\\$\\$\" ]; then");
    println!("    cd \"\\$(cat \\\"\\$RUNTIME_DIR/\\$\\$\\\")\"");
    println!("    rm \"\\$RUNTIME_DIR/\\$\\$\"");
    println!("  fi");
    println!("}}");
    println!("EOF");
    println!("  )\"");
}
EOF

