cat > /workspace/src/app.rs << 'EOF'
use std::path::{Path, PathBuf};
use std::fs;
use std::io;
use crossterm::event::{KeyEvent, KeyCode, KeyModifiers};
use std::collections::HashMap;

#[derive(Clone, Debug)]
pub struct FileEntry {
    pub name: String,
    pub path: PathBuf,
    pub is_dir: bool,
    pub size: u64,
    pub modified: u64,
    pub permissions: u32,
}

pub struct App {
    pub current_dir: PathBuf,
    pub entries: Vec<FileEntry>,
    pub cursor: usize,
    pub last_working_dir: Option<String>,
    pub show_preview: bool,
    pub preview_scroll: usize,
    pub split_preview: bool, // true = vertical, false = horizontal
    pub show_hidden: bool,
    pub sort_by_mtime: bool,
    pub command_mode: bool,
    pub command_buffer: String,
    pub search_mode: bool,
    pub search_buffer: String,
    pub visual_mode: bool,
    pub visual_start: usize,
    pub registers: HashMap<String, Vec<FileEntry>>,
    pub rename_mode: bool,
    pub rename_buffer: String,
    pub history: Vec<PathBuf>,
    pub history_index: usize,
    pub undo_stack: Vec<UndoAction>,
    pub redo_stack: Vec<UndoAction>,
}

#[derive(Clone, Debug)]
pub enum UndoAction {
    Delete(Vec<FileEntry>),
    Rename(FileEntry, String),
    Put(Vec<FileEntry>),
}

impl App {
    pub fn new(start_path: String) -> io::Result<Self> {
        let path = PathBuf::from(start_path);
        let mut app = App {
            current_dir: path,
            entries: Vec::new(),
            cursor: 0,
            last_working_dir: None,
            show_preview: false,
            preview_scroll: 0,
            split_preview: true,
            show_hidden: false,
            sort_by_mtime: false,
            command_mode: false,
            command_buffer: String::new(),
            search_mode: false,
            search_buffer: String::new(),
            visual_mode: false,
            visual_start: 0,
            registers: HashMap::new(),
            rename_mode: false,
            rename_buffer: String::new(),
            history: vec![path.clone()],
            history_index: 0,
            undo_stack: Vec::new(),
            redo_stack: Vec::new(),
        };
        app.registers.insert("0".to_string(), Vec::new());
        app.load_directory()?;
        Ok(app)
    }

    pub fn load_directory(&mut self) -> io::Result<()> {
        self.entries.clear();
        self.cursor = 0;
        self.preview_scroll = 0;

        if !self.current_dir.exists() {
            return Err(io::Error::new(io::ErrorKind::NotFound, "Directory not found"));
        }

        for entry in fs::read_dir(&self.current_dir)? {
            let entry = entry?;
            let path = entry.path();
            let name = path.file_name()
                .and_then(|n| n.to_str())
                .unwrap_or("???")
                .to_string();

            // Skip hidden files if not showing them
            if !self.show_hidden && name.starts_with('.') {
                continue;
            }

            let metadata = entry.metadata()?;
            let is_dir = metadata.is_dir();
            let size = metadata.len();
            let modified = metadata
                .modified()?
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap()
                .as_secs();

            #[cfg(unix)]
            let permissions = {
                use std::os::unix::fs::PermissionsExt;
                metadata.permissions().mode()
            };
            #[cfg(not(unix))]
            let permissions = 0;

            self.entries.push(FileEntry {
                name,
                path,
                is_dir,
                size,
                modified,
                permissions,
            });
        }

        // Sort entries
        if self.sort_by_mtime {
            self.entries.sort_by(|a, b| b.modified.cmp(&a.modified));
        } else {
            self.entries.sort_by(|a, b| {
                // Directories first, then by name
                if a.is_dir != b.is_dir {
                    return b.is_dir.cmp(&a.is_dir);
                }
                a.name.cmp(&b.name)
            });
        }

        Ok(())
    }

    pub fn handle_key_event(&mut self, key: KeyEvent) -> bool {
        if self.command_mode {
            return self.handle_command_key(key);
        }
        if self.search_mode {
            return self.handle_search_key(key);
        }
        if self.rename_mode {
            return self.handle_rename_key(key);
        }
        if self.visual_mode {
            return self.handle_visual_key(key);
        }

        match (key.code, key.modifiers) {
            (KeyCode::Char('q'), KeyModifiers::NONE) => return false,
            (KeyCode::Char('j'), KeyModifiers::NONE) | (KeyCode::Down, KeyModifiers::NONE) => {
                self.move_cursor_down(1);
            }
            (KeyCode::Char('k'), KeyModifiers::NONE) | (KeyCode::Up, KeyModifiers::NONE) => {
                self.move_cursor_up(1);
            }
            (KeyCode::Char('h'), KeyModifiers::NONE) | (KeyCode::Left, KeyModifiers::NONE) => {
                self.go_to_parent();
            }
            (KeyCode::Char('l'), KeyModifiers::NONE)
            | (KeyCode::Right, KeyModifiers::NONE)
            | (KeyCode::Enter, KeyModifiers::NONE) => {
                self.open_item();
            }
            (KeyCode::Char('g'), KeyModifiers::NONE) => {
                // Might be "gg"
                self.last_key_was_g = true;
            }
            (KeyCode::Char('G'), KeyModifiers::SHIFT) => {
                self.go_to_bottom();
            }
            (KeyCode::Char('v'), KeyModifiers::NONE) => {
                self.show_preview = !self.show_preview;
            }
            (KeyCode::Char(':'), KeyModifiers::NONE) => {
                self.command_mode = true;
                self.command_buffer.clear();
            }
            (KeyCode::Esc, _) => {
                self.search_buffer.clear();
                self.search_mode = false;
            }
            (KeyCode::Char('d'), KeyModifiers::CONTROL) => {
                self.move_cursor_down(10); // Half page down
            }
            (KeyCode::Char('u'), KeyModifiers::CONTROL) => {
                self.move_cursor_up(10); // Half page up
            }
            _ => {}
        }

        true
    }

    fn handle_command_key(&mut self, key: KeyEvent) -> bool {
        match key.code {
            KeyCode::Enter => {
                self.execute_command();
                self.command_mode = false;
                return true;
            }
            KeyCode::Esc => {
                self.command_mode = false;
                self.command_buffer.clear();
                return true;
            }
            KeyCode::Char(c) => {
                self.command_buffer.push(c);
            }
            KeyCode::Backspace => {
                self.command_buffer.pop();
            }
            _ => {}
        }
        true
    }

    fn execute_command(&mut self) {
        let cmd = self.command_buffer.trim();
        if cmd == "q" {
            std::process::exit(0);
        } else if cmd == "h" {
            // Show help - already handled in main
        } else if cmd.starts_with("cd") {
            let path = cmd[2..].trim();
            if path.is_empty() {
                if let Ok(home) = std::env::var("HOME") {
                    self.current_dir = PathBuf::from(home);
                }
            } else {
                self.current_dir = PathBuf::from(path);
            }
            let _ = self.load_directory();
        } else if cmd == "e" {
            let _ = self.load_directory();
        }
    }

    fn handle_search_key(&mut self, key: KeyEvent) -> bool {
        match key.code {
            KeyCode::Enter => {
                self.search_mode = false;
            }
            KeyCode::Esc => {
                self.search_mode = false;
                self.search_buffer.clear();
            }
            KeyCode::Char(c) => {
                self.search_buffer.push(c);
            }
            KeyCode::Backspace => {
                self.search_buffer.pop();
            }
            _ => {}
        }
        true
    }

    fn handle_rename_key(&mut self, key: KeyEvent) -> bool {
        match key.code {
            KeyCode::Enter => {
                self.rename_mode = false;
                // TODO: Perform rename
            }
            KeyCode::Esc => {
                self.rename_mode = false;
                self.rename_buffer.clear();
            }
            KeyCode::Char(c) => {
                self.rename_buffer.push(c);
            }
            KeyCode::Backspace => {
                self.rename_buffer.pop();
            }
            _ => {}
        }
        true
    }

    fn handle_visual_key(&mut self, key: KeyEvent) -> bool {
        match key.code {
            KeyCode::Char('y'), KeyModifiers::NONE => {
                // Yank selected
            }
            KeyCode::Char('d'), KeyModifiers::NONE => {
                // Delete and yank selected
            }
            KeyCode::Esc | KeyCode::Char('v'), KeyModifiers::NONE => {
                self.visual_mode = false;
            }
            _ => {
                self.handle_key_event(key)
            }
        }
        true
    }

    pub fn move_cursor_down(&mut self, count: usize) {
        self.cursor = std::cmp::min(self.cursor + count, self.entries.len().saturating_sub(1));
    }

    pub fn move_cursor_up(&mut self, count: usize) {
        self.cursor = self.cursor.saturating_sub(count);
    }

    pub fn go_to_bottom(&mut self) {
        self.cursor = self.entries.len().saturating_sub(1);
    }

    pub fn go_to_parent(&mut self) {
        if let Some(parent) = self.current_dir.parent() {
            self.current_dir = parent.to_path_buf();
            let _ = self.load_directory();
        }
    }

    pub fn open_item(&mut self) {
        if self.entries.is_empty() {
            return;
        }
        let entry = &self.entries[self.cursor];
        if entry.is_dir {
            self.current_dir = entry.path.clone();
            let _ = self.load_directory();
        }
    }

    pub fn current_entry(&self) -> Option<&FileEntry> {
        if self.cursor < self.entries.len() {
            Some(&self.entries[self.cursor])
        } else {
            None
        }
    }

    last_key_was_g: bool = false,
}
