            KeyCode::Esc => {
                self.command_mode = false;
                self.command_buffer.clear();
                return true;
            }
            KeyCode::Char(c) => {
                self.command_buffer.push(c);
            }
            KeyCode::Backspace => {
                self.command_buffer.pop();
            }
            _ => {}
        }
        true
    }

    fn execute_command(&mut self) {
        let cmd = self.command_buffer.trim();
        if cmd == "q" {
            std::process::exit(0);
        } else if cmd == "h" {
            // Show help - already handled in main
        } else if cmd.starts_with("cd") {
            let path = cmd[2..].trim();
            if path.is_empty() {
                if let Ok(home) = std::env::var("HOME") {
                    self.current_dir = PathBuf::from(home);
                }
            } else {
                self.current_dir = PathBuf::from(path);
            }
            let _ = self.load_directory();
        } else if cmd == "e" {
            let _ = self.load_directory();
        }
    }

    fn handle_search_key(&mut self, key: KeyEvent) -> bool {
        match key.code {
            KeyCode::Enter => {
                self.search_mode = false;
            }
            KeyCode::Esc => {
                self.search_mode = false;
                self.search_buffer.clear();
            }
            KeyCode::Char(c) => {
                self.search_buffer.push(c);
            }
            KeyCode::Backspace => {
                self.search_buffer.pop();
            }
            _ => {}
        }
        true
    }

    fn handle_rename_key(&mut self, key: KeyEvent) -> bool {
        match key.code {
            KeyCode::Enter => {
                self.rename_mode = false;
                // TODO: Perform rename
            }
            KeyCode::Esc => {
                self.rename_mode = false;
                self.rename_buffer.clear();
            }
            KeyCode::Char(c) => {
                self.rename_buffer.push(c);
            }
            KeyCode::Backspace => {
                self.rename_buffer.pop();
            }
            _ => {}
        }
        true
    }

    fn handle_visual_key(&mut self, key: KeyEvent) -> bool {
        match key.code {
            KeyCode::Char('y'), KeyModifiers::NONE => {
                // Yank selected
            }
            KeyCode::Char('d'), KeyModifiers::NONE => {
                // Delete and yank selected
            }
            KeyCode::Esc | KeyCode::Char('v'), KeyModifiers::NONE => {
                self.visual_mode = false;
            }
            _ => {
                self.handle_key_event(key)
            }
        }
        true
    }

    pub fn move_cursor_down(&mut self, count: usize) {
        self.cursor = std::cmp::min(self.cursor + count, self.entries.len().saturating_sub(1));
    }

    pub fn move_cursor_up(&mut self, count: usize) {
        self.cursor = self.cursor.saturating_sub(count);
    }

    pub fn go_to_bottom(&mut self) {
        self.cursor = self.entries.len().saturating_sub(1);
    }

    pub fn go_to_parent(&mut self) {
        if let Some(parent) = self.current_dir.parent() {
