fn format_entry_line(name: &str, is_dir: bool, size: u64, modified: u64) -> String {
    let type_str = if is_dir { "d" } else { "." };
    let size_str = format_size(size);
    let time_str = format_time(modified);

    // Pad name to 50 chars
    let padded_name = format!("{:<50}", name);
    format!("{}> {}                                                  {}  {}",
        type_str, padded_name, time_str, size_str)
}

fn format_status_line(app: &App) -> String {
    let idx = app.cursor + 1;
    let total = app.entries.len();

    let entry = &app.entries[app.cursor];
    let perms = if cfg!(unix) {
        format_permissions(entry.permissions)
    } else {
        "755".to_string()
    };

    let file_type = if entry.is_dir { "dir" } else { "file" };
    let size_str = format_size(entry.size);

    format!("{}/{} {} {} {}", idx, total, entry.name, file_type, perms)
}

fn format_size(size: u64) -> String {
    if size < 1024 {
        format!("{}B", size)
    } else if size < 1024 * 1024 {
        format!("{:.1}KB", size as f64 / 1024.0)
    } else if size < 1024 * 1024 * 1024 {
        format!("{:.1}MB", size as f64 / (1024.0 * 1024.0))
    } else {
        format!("{:.1}GB", size as f64 / (1024.0 * 1024.0 * 1024.0))
    }
}

fn format_time(timestamp: u64) -> String {
    match OffsetDateTime::from_unix_timestamp(timestamp as i64) {
        Ok(dt) => {
            // Format: YYYY-MM-DD HH:MM or similar
            format!("{:04}-{:02}-{:02} {:02}:{:02}",
                dt.year(),
                dt.month() as u8,
                dt.day(),
                dt.hour(),
                dt.minute()
            )
        }
        Err(_) => "????-??-?? ??:??".to_string(),
    }
}

fn format_permissions(mode: u32) -> String {
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        format!("{:o}", mode & 0o777)
    }
    #[cfg(not(unix))]
    {
        "755".to_string()
    }
}

fn format_dir_preview(path: &std::path::Path) -> String {
    match std::fs::read_dir(path) {
        Ok(entries) => {
            let items: Vec<String> = entries
                .filter_map(|e| e.ok())
                .take(20) // Limit preview to first 20 items
                .map(|e| {
                    let path = e.path();
                    let name = path.file_name()
                        .and_then(|n| n.to_str())
                        .unwrap_or("???")
                        .to_string();
                    if path.is_dir() {
                        format!("├ {}", name)
                    } else {
                        format!("├ {}", name)
                    }
                })
                .collect();
            items.join("\n")
        }
        Err(_) => "(error reading directory)".to_string(),
    }
}

fn format_file_preview(path: &std::path::Path) -> String {
    if !path.is_file() {
        return "(not a file)".to_string();
    }

    match std::fs::metadata(path) {
        Ok(metadata) => {
            if metadata.len() > 10_000_000 {
                return "(file too large)".to_string();
            }
        }
        Err(_) => return "(cannot read file)".to_string(),
    }

    match std::fs::read_to_string(path) {
        Ok(content) => {
            if content.len() > 10_000 {
                format!("{}...", &content[..10_000])
            } else {
                content
            }
        }
        Err(_) => "(binary file)".to_string(),
    }
}
