        run_app(cwd)
    }
}

fn run_app(start_path: String) -> io::Result<()> {
    let mut terminal = terminal::Terminal::new()?;
    terminal.init()?;

    let mut app = App::new(start_path)?;

    loop {
        terminal.draw(&app)?;

        if let Some(key) = terminal.get_key()? {
            if !app.handle_key(key) {
                break;
            }
        }
    }

    terminal.cleanup()?;

    if let Some(last_dir) = &app.last_working_dir {
        println!("{}", last_dir);
    }

    Ok(())
}

