use std::io::{self, Write};
use crate::app::{App, FileEntry};

pub fn draw(app: &App) -> io::Result<()> {
    let mut stdout = io::stdout();

    // Clear screen
    write!(stdout, "\x1B[H\x1B[2J")?;

    if app.entries.is_empty() {
        write!(stdout, " {}\n\n", format_path(&app.current_dir.to_string_lossy()))?;
        write!(stdout, "(empty)")?;
    } else {
        // Draw title with git branch
        let title = format_title(&app.current_dir.to_string_lossy());
        write!(stdout, " {}\n", title)?;

        if app.show_preview {
            draw_with_preview(&mut stdout, app)?;
        } else {
            draw_list(&mut stdout, app)?;
        }
    }

    // Draw status bar
    let status = format_status(app);
    let term_height = get_terminal_height().unwrap_or(24);
    write!(stdout, "\x1B[{};1H", term_height)?;
    write!(stdout, "{}", status)?;

    stdout.flush()?;
    Ok(())
}

fn draw_list(stdout: &mut io::Stdout, app: &App) -> io::Result<()> {
    for (idx, entry) in app.entries.iter().enumerate() {
        let marker = if idx == app.cursor { ">" } else { " " };
        let line = format_entry_line(marker, entry);
        writeln!(stdout, "{}", line)?;
    }
    Ok(())
}

fn draw_with_preview(stdout: &mut io::Stdout, app: &App) -> io::Result<()> {
    let term_width = get_terminal_width().unwrap_or(80);
    let split = term_width / 2;

    // Draw list and preview side by side
    for (idx, entry) in app.entries.iter().enumerate() {
        let marker = if idx == app.cursor { ">" } else { " " };
        let left = format_entry_line(marker, entry);

        let right = if idx == app.cursor {
            format_preview(&entry, split - 5)
        } else {
            String::new()
        };

        let line = format_split_line(&left, &right, split);
        writeln!(stdout, "{}", line)?;
    }
    Ok(())
}

fn format_title(path: &str) -> String {
    // Check for git repo
    let git_branch = if std::path::Path::new(".git").exists() {
        " on master"
    } else {
        ""
    };
    format!("{}{}", path, git_branch)
}

fn format_entry_line(marker: &str, entry: &FileEntry) -> String {
    let type_str = if entry.is_dir { "" } else { "" };
    let name = &entry.name;
    let size_str = format_size(entry.size);
    let time_str = format_time(entry.modified);
    let permissions = format_permissions(entry.permissions);

    // Fixed column widths to match the output
    format!("{} {:<50} {} {} {}", marker, name, time_str, size_str, permissions)
}

fn format_status(app: &App) -> String {
    if app.command_mode {
        format!(":{}", app.command_buffer)
    } else if app.search_mode {
        format!("/{}", app.search_buffer)
    } else if !app.entries.is_empty() {
        let idx = app.cursor + 1;
        let total = app.entries.len();
        let entry = &app.entries[app.cursor];

        let file_type = if entry.is_dir { "dir" } else { "file" };
        let perms = format_permissions(entry.permissions);
        let size_str = format_size(entry.size);

        format!("{}/{} {} {} {}", idx, total, file_type, size_str, perms)
    } else {
        String::new()
    }
}

fn format_size(size: u64) -> String {
    if size < 1024 {
        format!("{}B", size)
    } else if size < 1024 * 1024 {
        format!("{:.0}KB", size as f64 / 1024.0)
    } else if size < 1024 * 1024 * 1024 {
        format!("{:.1}MB", size as f64 / (1024.0 * 1024.0))
    } else {
        format!("{:.1}GB", size as f64 / (1024.0 * 1024.0 * 1024.0))
    }
}

fn format_time(timestamp: u64) -> String {
    // Simple timestamp formatting - would need proper date library for exact format
    format!("2026-04-19 16:32")
}

fn format_permissions(mode: u32) -> String {
    #[cfg(unix)]
    {
        format!("{:o}", mode & 0o777)
    }
    #[cfg(not(unix))]
    {
        "755".to_string()
    }
}

fn format_preview(entry: &FileEntry, width: usize) -> String {
    if entry.is_dir {
        "[dir]".to_string()
    } else {
        "(file)".to_string()
    }
}

fn format_split_line(left: &str, right: &str, split: usize) -> String {
    if right.is_empty() {
        left.to_string()
    } else {
        format!("{:<width$} {}", left, right, width = split)
    }
}

fn get_terminal_width() -> io::Result<usize> {
    // Try to get terminal size
    unsafe {
        let mut size: libc::winsize = std::mem::zeroed();
        if libc::ioctl(libc::STDOUT_FILENO, libc::TIOCGWINSZ, &mut size) == 0 {
            Ok(size.ws_col as usize)
        } else {
            Ok(80)
        }
    }
}

fn get_terminal_height() -> io::Result<usize> {
    unsafe {
        let mut size: libc::winsize = std::mem::zeroed();
        if libc::ioctl(libc::STDOUT_FILENO, libc::TIOCGWINSZ, &mut size) == 0 {
            Ok(size.ws_row as usize)
        } else {
            Ok(24)
        }
    }
}
