    let split = term_width / 2;

    // Draw list and preview side by side
    for (idx, entry) in app.entries.iter().enumerate() {
        let marker = if idx == app.cursor { ">" } else { " " };
        let left = format_entry_line(marker, entry);

        let right = if idx == app.cursor {
            format_preview(&entry, split - 5)
        } else {
