use std::io::{self, Read, Write};

pub struct Terminal;

impl Terminal {
    pub fn new() -> io::Result<Self> {
        Ok(Terminal)
    }

    pub fn init(&mut self) -> io::Result<()> {
        // Set up terminal in raw mode
        print!("\x1B[H\x1B[2J");
        io::stdout().flush()?;
        Ok(())
    }

    pub fn cleanup(&mut self) -> io::Result<()> {
        io::stdout().flush()?;
        Ok(())
    }

    pub fn get_key(&self) -> io::Result<Option<crate::app::Key>> {
        let mut buf = [0u8; 1];
        match io::stdin().read(&mut buf) {
            Ok(0) => Ok(None),
            Ok(1) => {
                let ch = buf[0];
                let key = match ch {
                    27 => {
                        // Escape sequence
                        let mut seq = [0u8; 2];
                        match io::stdin().read(&mut seq) {
                            Ok(2) => {
                                match seq {
                                    [91, 65] => crate::app::Key::Up,
                                    [91, 66] => crate::app::Key::Down,
                                    [91, 67] => crate::app::Key::Right,
                                    [91, 68] => crate::app::Key::Left,
                                    _ => return Ok(Some(crate::app::Key::Escape)),
                                }
                            }
                            _ => crate::app::Key::Escape,
                        }
                    }
                    4 => crate::app::Key::CtrlD,
                    21 => crate::app::Key::CtrlU,
                    3 => crate::app::Key::CtrlC,
                    13 => crate::app::Key::Enter,
                    8 | 127 => crate::app::Key::Backspace,
                    c => crate::app::Key::Char(c as char),
                };
                Ok(Some(key))
            }
            Err(e) => Err(e),
            _ => Ok(None),
        }
    }

    pub fn draw(&self, app: &crate::app::App) -> io::Result<()> {
        crate::ui::draw(app)
    }
}
