use std::io::{self, Write, BufRead, BufReader};
use std::env;
use std::process::{Command, Stdio};
use std::path::{PathBuf, Path};
use std::fs;

mod app;
mod ui;

use app::App;

fn main() -> io::Result<()> {
    let args: Vec<String> = env::args().collect();

    if args.len() > 1 {
        match args[1].as_str() {
            "-h" | "--help" => {
                print_help();
                return Ok(());
            }
            "-l" | "--log" => {
                run_with_log()
            }
            "--init" => {
                print_init();
                return Ok(());
            }
            path => {
                run_app(path.to_string())
            }
        }
    } else {
        let cwd = env::current_dir()?.to_string_lossy().to_string();
        run_app(cwd)
    }
}

fn run_app(start_path: String) -> io::Result<()> {
    // Verify terminal size is available
    let (cols, rows) = get_terminal_size()?;
    if cols == 0 || rows == 0 {
        eprintln!("Error: Cannot detect terminal size");
        return Err(io::Error::new(io::ErrorKind::Other, "Cannot detect terminal size"));
    }

    let mut app = App::new(start_path)?;

    // Draw initial UI
    ui::draw(&app, cols as usize, rows as usize)?;

    Ok(())
}

fn run_with_log() -> io::Result<()> {
    let cwd = env::current_dir()?.to_string_lossy().to_string();
    run_app(cwd)
}

fn get_terminal_size() -> io::Result<(u16, u16)> {
    // Try using stty
    if let Ok(output) = Command::new("stty").arg("size").output() {
        let stdout = String::from_utf8_lossy(&output.stdout);
        let parts: Vec<&str> = stdout.trim().split_whitespace().collect();
        if parts.len() == 2 {
            if let (Ok(rows), Ok(cols)) = (parts[0].parse::<u16>(), parts[1].parse::<u16>()) {
                return Ok((cols, rows));
            }
        }
    }

    // Try using tput
    if let Ok(cols_out) = Command::new("tput").arg("cols").output() {
        if let Ok(rows_out) = Command::new("tput").arg("lines").output() {
            let cols_str = String::from_utf8_lossy(&cols_out.stdout);
            let rows_str = String::from_utf8_lossy(&rows_out.stdout);

            if let (Ok(cols), Ok(rows)) = (cols_str.trim().parse::<u16>(), rows_str.trim().parse::<u16>()) {
                return Ok((cols, rows));
            }
        }
    }

    // Check COLUMNS and LINES env vars
    let cols = env::var("COLUMNS")
        .ok()
        .and_then(|s| s.parse::<u16>().ok())
        .unwrap_or(80);
    let rows = env::var("LINES")
        .ok()
        .and_then(|s| s.parse::<u16>().ok())
        .unwrap_or(24);

    if cols > 0 && rows > 0 {
        Ok((cols, rows))
    } else {
        Ok((0, 0))
