        .and_then(|s| s.parse::<u16>().ok())
        .unwrap_or(80);
    let rows = env::var("LINES")
        .ok()
        .and_then(|s| s.parse::<u16>().ok())
        .unwrap_or(24);

    if cols > 0 && rows > 0 {
        Ok((cols, rows))
    } else {
        Ok((0, 0))
    }
