fn get_terminal_size() -> io::Result<(u16, u16)> {
    // Try using stty
    if let Ok(output) = Command::new("stty").arg("size").output() {
        let stdout = String::from_utf8_lossy(&output.stdout);
        let parts: Vec<&str> = stdout.trim().split_whitespace().collect();
        if parts.len() == 2 {
            if let (Ok(rows), Ok(cols)) = (parts[0].parse::<u16>(), parts[1].parse::<u16>()) {
                return Ok((cols, rows));
            }
        }
    }

    // Try using tput
    if let Ok(cols_out) = Command::new("tput").arg("cols").output() {
        if let Ok(rows_out) = Command::new("tput").arg("lines").output() {
            let cols_str = String::from_utf8_lossy(&cols_out.stdout);
            let rows_str = String::from_utf8_lossy(&rows_out.stdout);

            if let (Ok(cols), Ok(rows)) = (cols_str.trim().parse::<u16>(), rows_str.trim().parse::<u16>()) {
                return Ok((cols, rows));
            }
        }
    }

    // Check COLUMNS and LINES env vars
    let cols = env::var("COLUMNS")
        .ok()
        .and_then(|s| s.parse::<u16>().ok())
        .unwrap_or(80);
    let rows = env::var("LINES")
        .ok()
        .and_then(|s| s.parse::<u16>().ok())
        .unwrap_or(24);

    if cols > 0 && rows > 0 {
        Ok((cols, rows))
    } else {
        Ok((0, 0))
    }
}

