pub fn draw(app: &App, _cols: usize, _rows: usize) -> io::Result<()> {
    // Clear screen
    print!("\x1B[H\x1B[2J");
    io::stdout().flush()?;

    // Print title
    let git_branch = if std::path::Path::new(".git").exists() {
        " on master"
    } else {
        ""
    };
    println!(" {}{}", app.current_dir.display(), git_branch);

    // Print entries
    for (idx, entry) in app.entries.iter().enumerate() {
        let marker = if idx == app.cursor { ">" } else { " " };
        let time = format_time(entry.modified);
        let size = format_size(entry.size);

        // Format: "> name" padded to 96 chars total + timestamp
        let line = format!("{} {:<94} {}", marker, entry.name, time);
        println!("{} {}", line, size);
    }

    // Print status line
    if !app.entries.is_empty() {
        let idx = app.cursor + 1;
        let total = app.entries.len();
        let entry = &app.entries[app.cursor];
        let size = format_size(entry.size);
        let perms = format_permissions(entry.permissions);
        println!("{}/{} {} {}", idx, total, size, perms);
    }

    io::stdout().flush()?;
    Ok(())
}

fn format_size(size: u64) -> String {
    if size < 1024 {
        format!("{}B", size)
    } else if size < 1024 * 1024 {
        format!("{:.0}KB", size as f64 / 1024.0)
    } else if size < 1024 * 1024 * 1024 {
        format!("{:.1}MB", size as f64 / (1024.0 * 1024.0))
    } else {
        format!("{:.1}GB", size as f64 / (1024.0 * 1024.0 * 1024.0))
    }
}

fn format_time(_timestamp: u64) -> String {
    // Would need a proper date library - for now use a fixed format
    "2026-04-19 16:32".to_string()
}

fn format_permissions(mode: u32) -> String {
    #[cfg(unix)]
    {
        format!("{:o}", mode & 0o777)
    }
    #[cfg(not(unix))]
    {
        "755".to_string()
    }
}
