use std::io::{self, Write, Read};
use std::env;
use std::process::Command;
use std::fs;
use std::path::PathBuf;

mod app;
mod ui;

use app::App;

fn main() -> io::Result<()> {
    let args: Vec<String> = env::args().collect();

    if args.len() > 1 {
        match args[1].as_str() {
            "-h" | "--help" => {
                print_help();
                return Ok(());
            }
            "-l" | "--log" => {
                run_with_log()
            }
            "--init" => {
                print_init();
                return Ok(());
            }
            path => {
                run_app(path.to_string())
            }
        }
    } else {
        let cwd = env::current_dir()?.to_string_lossy().to_string();
        run_app(cwd)
    }
}

fn run_app(start_path: String) -> io::Result<()> {
    // Verify terminal size is available
    let (cols, rows) = get_terminal_size()?;
    if cols == 0 || rows == 0 {
        eprintln!("Error: Cannot detect terminal size");
        return Err(io::Error::new(io::ErrorKind::Other, "Cannot detect terminal size"));
    }

    let mut app = App::new(start_path)?;

    // Set terminal to raw mode and draw UI
    setup_terminal()?;
    ui::draw(&app, cols as usize, rows as usize)?;

    // Main event loop
    loop {
        if let Some(key) = read_input()? {
            match key.as_str() {
                "q" => {
                    cleanup_terminal()?;
                    return Ok(());
                }
                "j" | "Down" => app.move_down(),
                "k" | "Up" => app.move_up(),
                "h" | "Left" => app.go_parent(),
                "l" | "Right" | "Enter" => app.open_item(),
                "g" => app.mark_g(),
                "G" => app.go_end(),
                "gg" => app.go_start(),
                "v" => app.toggle_preview(),
                _ => {}
            }

            ui::draw(&app, cols as usize, rows as usize)?;
        }
    }
}

fn run_with_log() -> io::Result<()> {
    let cwd = env::current_dir()?.to_string_lossy().to_string();
    run_app(cwd)
}

fn get_terminal_size() -> io::Result<(u16, u16)> {
    if let Ok(output) = Command::new("tput").arg("cols").output() {
        if let Ok(output2) = Command::new("tput").arg("lines").output() {
            let cols_str = String::from_utf8_lossy(&output.stdout);
            let rows_str = String::from_utf8_lossy(&output2.stdout);

            if let (Ok(cols), Ok(rows)) = (cols_str.trim().parse::<u16>(), rows_str.trim().parse::<u16>()) {
                return Ok((cols, rows));
            }
        }
    }

    let cols = env::var("COLUMNS")
        .ok()
        .and_then(|s| s.parse::<u16>().ok())
        .unwrap_or(80);
    let rows = env::var("LINES")
        .ok()
        .and_then(|s| s.parse::<u16>().ok())
        .unwrap_or(24);

    Ok((cols, rows))
}

fn setup_terminal() -> io::Result<()> {
    // Try to set raw mode using stty
    let _ = Command::new("stty")
        .args(&["raw", "-echo"])
        .spawn()?
        .wait();
    Ok(())
}

fn cleanup_terminal() -> io::Result<()> {
    let _ = Command::new("stty")
        .args(&["cooked", "echo"])
        .spawn()?
        .wait();
    Ok(())
}

fn read_input() -> io::Result<Option<String>> {
    let mut buffer = [0; 1];
    match io::stdin().read(&mut buffer) {
        Ok(1) => {
            Ok(Some(format!("{}", buffer[0] as char)))
        }
        Ok(_) => Ok(None),
        Err(e) => Err(e),
    }
}

