use std::path::PathBuf;
use std::fs;
use std::io;

#[derive(Clone, Debug)]
pub struct FileEntry {
    pub name: String,
    pub path: PathBuf,
    pub is_dir: bool,
    pub size: u64,
    pub modified: u64,
    pub permissions: u32,
}

pub struct App {
    pub current_dir: PathBuf,
    pub entries: Vec<FileEntry>,
    pub cursor: usize,
    pub last_working_dir: Option<String>,
    pub show_preview: bool,
    pub last_was_g: bool,
}

impl App {
    pub fn new(start_path: String) -> io::Result<Self> {
        let path = PathBuf::from(start_path);
        let mut app = App {
            current_dir: path,
            entries: Vec::new(),
            cursor: 0,
            last_working_dir: None,
            show_preview: false,
            last_was_g: false,
        };
        app.load_directory()?;
        Ok(app)
    }

    pub fn load_directory(&mut self) -> io::Result<()> {
        self.entries.clear();
        self.cursor = 0;

        if !self.current_dir.exists() {
            return Err(io::Error::new(io::ErrorKind::NotFound, "Directory not found"));
        }

        for entry in fs::read_dir(&self.current_dir)? {
            let entry = entry?;
            let path = entry.path();
            let name = path.file_name()
                .and_then(|n| n.to_str())
                .unwrap_or("???")
                .to_string();

            let metadata = entry.metadata()?;
            let is_dir = metadata.is_dir();
            let size = metadata.len();
            let modified = metadata
                .modified()?
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap()
                .as_secs();

            #[cfg(unix)]
            let permissions = {
                use std::os::unix::fs::PermissionsExt;
                metadata.permissions().mode()
            };
            #[cfg(not(unix))]
            let permissions = 0;

            self.entries.push(FileEntry {
                name,
                path,
                is_dir,
                size,
                modified,
                permissions,
            });
        }

        self.entries.sort_by(|a, b| {
            if a.is_dir != b.is_dir {
                return b.is_dir.cmp(&a.is_dir);
            }
            a.name.cmp(&b.name)
        });

        Ok(())
    }

    pub fn move_down(&mut self) {
        if self.cursor < self.entries.len().saturating_sub(1) {
            self.cursor += 1;
        }
    }

    pub fn move_up(&mut self) {
        if self.cursor > 0 {
            self.cursor -= 1;
        }
    }

    pub fn go_start(&mut self) {
        self.cursor = 0;
    }

    pub fn go_end(&mut self) {
        self.cursor = self.entries.len().saturating_sub(1);
    }

    pub fn go_parent(&mut self) {
        if let Some(parent) = self.current_dir.parent() {
            self.current_dir = parent.to_path_buf();
            let _ = self.load_directory();
        }
    }

    pub fn open_item(&mut self) {
        if let Some(entry) = self.entries.get(self.cursor) {
            if entry.is_dir {
                self.current_dir = entry.path.clone();
                let _ = self.load_directory();
            }
        }
    }

    pub fn mark_g(&mut self) {
        self.last_was_g = true;
    }

    pub fn toggle_preview(&mut self) {
        self.show_preview = !self.show_preview;
    }
}
